public class VolumeCalculator {
    protected List<SolidShape> solidShapes;

    public VolumeCalculator(List<SolidShape> solidShapes) {
        this.solidShapes = solidShapes;
    }

    public double calculateTotalVolume() {
        double totalVolume = 0;
        for (SolidShape solid : solidShapes) {
            totalVolume += solid.volume();
        }
        return totalVolume;
    }
}

interface SolidShape {
    double volume();
}

class Sphere implements SolidShape {
    private double radius;

    public Sphere(double radius) {
        this.radius = radius;
    }

    @Override
    public double volume() {
        return (4/3) * Math.PI * Math.pow(this.radius, 3);
    }
}
